// Package awskms provides a crypto.KeyProvider backed by AWS KMS, the
// key-encryption key staying in KMS and never reaching this process.
//
// Data keys are generated by KMS itself through GenerateDataKey, which returns
// the plaintext key and its wrapped form in one call, so the engine holds a
// data key only for as long as it takes to seal one object.
package awskms

import (
	"context"
	"errors"
	"fmt"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/kms"
	"github.com/aws/aws-sdk-go-v2/service/kms/types"
	"github.com/newstack-cloud/bluelink/libs/common/crypto"
)

// Client is the subset of the KMS API a key provider uses.
//
// Narrowed to these two calls so a caller can supply a client with its own
// retry, endpoint or credential behaviour, and so the provider is testable
// without reaching AWS.
type Client interface {
	GenerateDataKey(
		ctx context.Context,
		params *kms.GenerateDataKeyInput,
		optFns ...func(*kms.Options),
	) (*kms.GenerateDataKeyOutput, error)
	Decrypt(
		ctx context.Context,
		params *kms.DecryptInput,
		optFns ...func(*kms.Options),
	) (*kms.DecryptOutput, error)
}

type keyProvider struct {
	client Client
	keyID  string
}

// NewKeyProvider returns a key provider that wraps data keys with the KMS key
// the given id names, which may be a key id, ARN, alias name or alias ARN.
//
// The id is recorded in every envelope the provider seals, so it must stay
// stable for the life of the data. An alias is the better choice where a
// deployment expects to move to a new key, since KMS resolves it at the time
// of each call and KMS key rotation keeps old key material for decryption.
func NewKeyProvider(client Client, keyID string) (crypto.KeyProvider, error) {
	if client == nil {
		return nil, errors.New("awskms: a client is required")
	}
	if keyID == "" {
		return nil, errors.New("awskms: a key id is required")
	}

	return &keyProvider{client: client, keyID: keyID}, nil
}

func (p *keyProvider) ID() string {
	return fmt.Sprintf("awskms:%s", p.keyID)
}

// The scope is unused as a round trip per object is the price of the key never
// leaving KMS, and a provider that cached keys per scope would be trading that
// for latency. Reuse belongs here rather than in callers if it is ever needed.
func (p *keyProvider) GenerateDataKey(
	ctx context.Context,
	scope string,
) (plaintext []byte, wrapped []byte, err error) {
	out, err := p.client.GenerateDataKey(ctx, &kms.GenerateDataKeyInput{
		KeyId:   aws.String(p.keyID),
		KeySpec: types.DataKeySpecAes256,
	})
	if err != nil {
		return nil, nil, fmt.Errorf("awskms: generating a data key: %w", err)
	}

	if len(out.Plaintext) != crypto.DEKSize {
		return nil, nil, fmt.Errorf(
			"awskms: kms returned a %d byte data key, expected %d",
			len(out.Plaintext),
			crypto.DEKSize,
		)
	}

	if len(out.CiphertextBlob) == 0 {
		return nil, nil, errors.New("awskms: kms returned an empty wrapped data key")
	}

	return out.Plaintext, out.CiphertextBlob, nil
}

func (p *keyProvider) UnwrapKey(
	ctx context.Context,
	kekID string,
	wrapped []byte,
) ([]byte, error) {
	if kekID != p.ID() {
		return nil, fmt.Errorf(
			"awskms: envelope was sealed with key %q, this provider holds %q",
			kekID,
			p.ID(),
		)
	}

	// The key id is passed on decryption as well as encryption so that KMS
	// uses the key this provider is configured with rather than the one named
	// in the ciphertext, which is what makes a swapped ciphertext fail.
	out, err := p.client.Decrypt(ctx, &kms.DecryptInput{
		KeyId:          aws.String(p.keyID),
		CiphertextBlob: wrapped,
	})
	if err != nil {
		return nil, fmt.Errorf("awskms: unwrapping a data key: %w", err)
	}

	if len(out.Plaintext) != crypto.DEKSize {
		return nil, fmt.Errorf(
			"awskms: kms returned a %d byte data key, expected %d",
			len(out.Plaintext),
			crypto.DEKSize,
		)
	}

	return out.Plaintext, nil
}
